<script lang="ts">
 import{onMount,onDestroy}from'svelte';import{get,post,upload}from'$lib/api';
 let{onready}:{onready?:(outputId:string)=>Promise<void>}=$props();
 let output=$state(''),jobStatus=$state('');let polls=0;let tracking=true,timer:ReturnType<typeof setTimeout>|undefined;onDestroy(()=>{tracking=false;if(timer)clearTimeout(timer)});
 async function poll(id:string){if(++polls>360){error="Tracking paused. Check Activity for the current provider status.";return}try{const result=await get('/render-jobs/'+id);if(!tracking||job!==id)return;jobStatus=result.job?.status??'';if(jobStatus==='succeeded'){output=result.outputs?.[0]?.id??'';return}if(['failed','reconciliation_required','canceled'].includes(jobStatus)){error=result.job?.error||'Generation needs attention in Activity.';return}}catch{if(!tracking)return}if(tracking&&job===id)timer=setTimeout(()=>void poll(id),5000)}
 let assets=$state<any[]>([]),references=$state<any[]>([]),prompt=$state(''),duration=$state(8),aspect=$state('9:16'),resolution=$state('720p'),audio=$state(true),busy=$state(false),error=$state(''),plan=$state<any>(null),job=$state('');let plannedRequest='';
 const body=()=>({prompt,duration,aspect_ratio:aspect,resolution,generate_audio:audio,references});
 onMount(()=>{void get('/assets').then(result=>assets=result).catch(e=>error=String(e))});
 function kind(asset:any){const path=asset.file_path??'';return /\.(png|jpe?g|gif|webp)$/i.test(path)?'image':/\.(mp4|mov)$/i.test(path)?'video':/\.(mp3|wav)$/i.test(path)?'audio':''}
 async function attach(file?:File){if(!file)return;busy=true;try{if(file.size>50*1024*1024)throw Error('Upload a reference smaller than 50 MB');const data=new FormData();data.append('file',file);data.append('type','other');const asset=await upload('/assets/upload',data);assets=[asset,...assets];add(asset.id)}catch(e){error=String(e)}finally{busy=false}}
 function add(id:string){const asset=assets.find(a=>a.id===id);if(!asset||references.some(r=>r.asset_id===id))return;const type=kind(asset);references=[...references,{asset_id:id,kind:type,purpose:type==='video'?'Camera and movement':type==='audio'?'Sound and rhythm':'Visual appearance'}];plan=null}
 async function check(){busy=true;error='';try{const request=body();plan=await post('/reference-videos/plan',request);plannedRequest=JSON.stringify(request)}catch(e){error=String(e)}finally{busy=false}}
 async function generate(){if(plannedRequest!==JSON.stringify(body())){plan=null;error='Settings changed. Check the plan again.';return}busy=true;error='';try{const result=await post('/reference-videos/render',{...body(),confirmed_plan_id:plan.id});job=result.job_id;polls=0;if(timer)clearTimeout(timer);output='';plan=null;void poll(job)}catch(e){error=String(e)}finally{busy=false}}
</script>
<details class="rounded-lg border border-border p-4"><summary class="min-h-11 cursor-pointer py-3 text-sm font-medium">Make a new clip with AI <span class="block text-xs font-normal text-muted-foreground">From your images, video or audio · uses credits</span></summary><div class="space-y-3"><p class="text-xs text-muted-foreground">Uses fal Seedance 2.0 Fast reference mode. This sends the selected media to generation, separately from extracting a style. Provider credits apply.</p><fieldset disabled={busy} class="space-y-3"><label class="grid gap-1 text-sm">Upload generation reference<input type="file" accept="image/png,image/jpeg,image/webp,image/gif,video/mp4,video/quicktime,audio/mpeg,audio/wav" onchange={e=>{void attach(e.currentTarget.files?.[0]);e.currentTarget.value=''}}/></label><label class="grid gap-1 text-sm">Library reference<select value="" onchange={e=>add(e.currentTarget.value)}><option value="">Add an image, video or audio file…</option>{#each assets.filter(a=>kind(a)) as asset}<option value={asset.id}>{asset.name} · {kind(asset)}</option>{/each}</select></label>
 {#each references as ref,i(ref.asset_id)}<div class="space-y-1 rounded-md border border-border p-2"><p class="text-sm">{assets.find(a=>a.id===ref.asset_id)?.name} · {ref.kind}</p><label class="grid gap-1 text-xs">Reference role<input maxlength="200" value={ref.purpose} oninput={e=>{references=references.map((r,j)=>j===i?{...r,purpose:e.currentTarget.value}:r);plan=null}}/></label><button onclick={()=>{references=references.filter((_,j)=>j!==i);plan=null}}>Remove reference</button></div>{/each}
 <label class="grid gap-1 text-sm">Generation direction<textarea rows="3" bind:value={prompt} oninput={()=>plan=null} placeholder="Describe the action and how to use the reference movement, appearance and sound…"></textarea></label><div class="grid grid-cols-2 gap-3"><label class="grid gap-1 text-sm">Clip duration<select bind:value={duration} onchange={()=>plan=null}>{#each Array.from({length:12},(_,i)=>i+4) as seconds}<option value={seconds}>{seconds} seconds</option>{/each}</select></label><label class="grid gap-1 text-sm">Video size<select bind:value={resolution} onchange={()=>plan=null}><option value="480p">480p</option><option value="720p">720p</option></select></label></div><label class="grid gap-1 text-sm">Format<select bind:value={aspect} onchange={()=>plan=null}><option value="9:16">Portrait · 9:16</option><option value="16:9">Landscape · 16:9</option><option value="1:1">Square · 1:1</option></select></label><label class="flex items-center gap-2 text-sm"><input class="!w-auto" type="checkbox" bind:checked={audio} onchange={()=>plan=null}/>Generate native audio</label><p class="text-xs text-muted-foreground">Up to 9 images, 3 videos and 3 audio files, 12 total. Videos: 2–15 seconds combined, approximately 480p–720p. Audio: at most 15 seconds combined. At least one image/video is required. Studio upload limits also apply.</p><button disabled={!prompt.trim()||!references.length} onclick={check}>Check generation plan</button>
 {#if plan}<div class="space-y-2 border-t border-border pt-3"><p class="text-sm">{plan.new_calls} new video call · {plan.generated_seconds} generated seconds</p><p class="text-xs text-muted-foreground">Matching existing clips are reused. This does not promise exact voice identity or frame timing.</p><button onclick={generate}>{plan.new_calls?'Generate this reference clip':'Use existing generation'}</button></div>{/if}</fieldset>{#if busy}<p role="status" class="text-sm">Preparing the reference request…</p>{/if}{#if error}<p role="alert" class="text-sm text-destructive">{error}</p>{/if}{#if job}<p role="status" class="text-sm">Generation {jobStatus||'queued'}. <a class="underline" href={`/render?job_id=${job}`}>Open job details</a></p>{/if}{#if output&&onready}<button disabled={busy} onclick={async()=>{busy=true;try{await onready?.(output);output=''}catch(e){error=String(e)}finally{busy=false}}}>Add generated clip to this edit</button>{/if}</div></details>
<style>input,select,textarea,button{min-height:44px;border:1px solid var(--border);border-radius:6px;padding:8px;background:var(--background);color:var(--foreground);width:100%;min-width:0}button{width:auto;background:var(--secondary);font-size:13px}button:disabled{opacity:.5}input:focus-visible,select:focus-visible,textarea:focus-visible,button:focus-visible{outline:2px solid var(--ring);outline-offset:2px}</style>
